import h5py,numpy as np
for p in ['data/sub-m17/sub-m17_ses-01_behavior+ophys.nwb','data/sub-m18/sub-m18_ses-01_behavior+ophys.nwb']:
 print('\n',p)
 with h5py.File(p,'r') as f:
  for kind in ['Fluorescence','Neuropil','Deconvolved']:
   g=f[f'processing/ophys/{kind}']; print(kind,list(g.keys()))
   for k in g: print(' ',k, g[k]['data'].shape if isinstance(g[k],h5py.Group) and 'data' in g[k] else '')
  seg=f['processing/ophys/ImageSegmentation/PlaneSegmentation']
  plane=seg['planeIdx'][:]; iscell=seg['iscell'][:,0]>0
  print('roi',len(plane),'plane counts',np.unique(plane,return_counts=True),'curated',[(x,int(np.sum(iscell&(plane==x)))) for x in np.unique(plane)])
  print('plane first/last/transitions',plane[:20],plane[-20:],np.flatnonzero(np.diff(plane))[:20])
